'use strict';

// MAIN //

/**
* Returns defaults.
*
* @private
* @returns {Object} defaults
*
* @example
* var obj = defaults();
* // returns {...}
*/
function defaults() {
	return {
		// Object mapping data field names to encoding channels:
		'channels': {
			'x': 'x',
			'y': 'y'
		},

		// Chart data:
		'data': [],

		// Data labels:
		'labels': [],

		// x-axis scale type:
		'xScaleType': 'linear',

		// x-axis label:
		'xTitle': 'x',

		// y-axis scale type:
		'yScaleType': 'linear',

		// y-axis label:
		'yTitle': 'y'
	};
}


// EXPORTS //

module.exports = defaults;
